package bank

import (
	"encoding/json"
	"math/big"
	"strings"
	"testing"
)

// Explicitly synthetic Decimal-only expectations from pinned Python AST.
func TestResourceAmountSourceOracle(t *testing.T) {
	var records []struct {
		Input string  `json:"input"`
		Wire  *string `json:"wire"`
	}
	if err := json.Unmarshal([]byte(amountSourceOracle), &records); err != nil {
		t.Fatal(err)
	}
	for _, tc := range records {
		t.Run(tc.Input, func(t *testing.T) {
			amount, parseErr := ParseDecimal(tc.Input)
			if parseErr != nil {
				if tc.Wire != nil {
					t.Fatal("native decimal rejected source amount")
				}
				return
			}
			wire, err := resourceTransferAmount(amount)
			if tc.Wire == nil {
				if err == nil {
					t.Fatal("source rejected amount accepted")
				}
				return
			}
			if err != nil || wire != *tc.Wire {
				t.Fatalf("wire=%q want=%q err=%v", wire, *tc.Wire, err)
			}
		})
	}
}
func FuzzResourceTransferAmountExact(f *testing.F) {
	for _, s := range []string{"10.50", "1.000", "999999999999999.000", "1e100000000", "0.001", "1.000000000000000000"} {
		f.Add(s)
	}
	f.Fuzz(func(t *testing.T, text string) {
		if len(text) > 512 {
			return
		}
		amount, err := ParseDecimal(text)
		if err != nil {
			return
		}
		wire, err := resourceTransferAmount(amount)
		if err != nil {
			return
		}
		if amount.Sign() <= 0 || len(wire) > 18 || strings.ContainsAny(wire, "eE+-") {
			t.Fatal("invalid accepted wire")
		}
		actual, ok := new(big.Rat).SetString(wire)
		if !ok {
			t.Fatal("invalid fixed decimal")
		}
		expected, ok := new(big.Rat).SetString(amount.String())
		if !ok || actual.Cmp(expected) != 0 {
			t.Fatal("financial amount changed")
		}
		parts := strings.Split(wire, ".")
		if len(parts[0]) > 15 || (len(parts) == 2 && len(parts[1]) > 2) {
			t.Fatal("precision limit bypass")
		}
	})
}

